export function gatePage(title, error) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>${title} · Many Worlds</title>
<link rel="icon" href="/favicon.svg" type="image/svg+xml">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500&family=Newsreader:opsz,wght@6..72,300;6..72,400&display=swap" rel="stylesheet">
<style>
:root{--paper:#fff;--ink:#0b0b0d;--graphite:#66666d;--hairline:#e6e7ea;--signal:#0057ff;--err:#b3261e}
@media (prefers-color-scheme:dark){:root{--paper:#0d0e11;--ink:#f1f1f3;--graphite:#9b9ba3;--hairline:#24262c;--signal:#5b93ff;--err:#ff8a80;color-scheme:dark}}
*{box-sizing:border-box}
body{margin:0;min-height:100vh;display:grid;place-items:center;background:var(--paper);color:var(--ink);font:16px/1.5 "Geist",-apple-system,"Helvetica Neue",Arial,sans-serif;padding:24px max(16px,env(safe-area-inset-left,0px))}
main{width:100%;max-width:360px;display:grid;gap:20px}
.mark{display:flex;align-items:center;gap:10px;font-family:"Newsreader",Georgia,serif;font-size:1.15rem}
.mark svg{width:28px;height:28px}
h1{font-family:"Newsreader",Georgia,serif;font-weight:300;font-size:2rem;line-height:1.1;margin:0}
p{margin:0;color:var(--graphite);font-size:.9rem}
form{display:grid;gap:10px}
label{font-size:.75rem;letter-spacing:.08em;text-transform:uppercase;color:var(--graphite)}
input{font:inherit;padding:12px;border:1px solid var(--hairline);background:var(--paper);color:var(--ink);border-radius:0}
input:focus{outline:2px solid var(--signal);outline-offset:1px}
button{font:500 .95rem/1 inherit;font-family:inherit;padding:13px;border:0;background:var(--ink);color:var(--paper);cursor:pointer;border-radius:0}
.err{color:var(--err);font-size:.85rem}
</style></head><body><main>
<div class="mark"><svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="11" cy="24" r="5" fill="none" stroke="currentColor" stroke-width="2.4"/><circle cx="17" cy="24" r="11" fill="none" stroke="currentColor" stroke-width="2.4"/><circle cx="24" cy="24" r="18" fill="none" stroke="currentColor" stroke-width="2.4" opacity=".45"/><circle cx="6" cy="24" r="3.4" fill="var(--signal)"/></svg>Many Worlds</div>
<h1>${title}</h1>
<p>Confidential investment memorandum. Enter the password to open it.</p>
<form method="post">
<label for="password">Password</label>
<input id="password" name="password" type="password" autocomplete="current-password" required autofocus>
${error ? '<div class="err" role="alert">Wrong password. Try again.</div>' : ''}
<button type="submit">Open memo</button>
</form>
</main></body></html>`;
}
